// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        // Ensure the contract has enough CLP to allow deposit? No – depositAndStake will fail anyway due to not being operator.
        // The rule: only operator (address(this)) or owner (address(this)) can call depositAndStake without revert.
        // For any other caller, it reverts. The mutant makes owner() return address(0), so a caller that is not operator
        // but is address(0) should also revert, but address(0) can’t call.
        // Simpler: We test that a random caller (not operator, not owner) causes revert.
        vm.prank(caller);
        bool reverted;
        try c.depositAndStake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // In original, owner() returns address(this), so only caller == operator works; for any other caller it reverts.
        // In mutant, owner() returns address(0), so caller == address(0) would be considered owner, but address(0) can't initiate
        // a call, so the behavior is the same as original for all non-zero callers. The given difference is via owner() return value,
        // but the test must catch that difference through the public interface. However the problem states the difference manifests
        // via depositAndStake – but only if the caller is address(0) which is impossible.
        // The difference: owner() returns different values when called. So we test that directly.
        // Reset: We check the return of owner() when called by a non-operator that is not the owner.
        vm.prank(caller);
        address ownerReturn = c.owner();
        // In original, this should return address(this). In mutant, it returns address(0).
        // The test must assert a rule that is true for original and false for mutant.
        // The condition: owner() returns the original deployer (address(this)) for any caller.
        assertTrue(ownerReturn == address(this), "owner() should return the deployer");
    }
}

