pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= 1e30);

        // Record the current rewardsRecipient
        address prev = c.rewardsRecipient();
        address expected = prev;

        // We need to set some initial value for rewardsRecipient that is not address(0)
        // because the constructor leaves it as address(0) and the bug sets it to address(0)
        // Let's set it to a non-zero address first via the owner
        if (prev == address(0)) {
            c.setRewardsRecipient(address(1));
            prev = address(1);
            expected = prev;
        }

        // Call depositAndStake - this should not change rewardsRecipient
        // But we need to handle the revert due to booster not being set up
        // The function may revert if isCvxShutdown() is true or other issues
        // Since we cannot set up the booster in test, we expect revert
        // But the claim is: depositAndStake does not modify rewardsRecipient regardless
        try c.depositAndStake(amount) {} catch {}

        // After the call, rewardsRecipient should remain unchanged
        assertTrue(c.rewardsRecipient() == expected, "rewardsRecipient should not change after depositAndStake");
    }
}

